WITH page_returns AS (SELECT wp.wp_web_page_sk, wp.wp_url, wp.wp_web_page_id, wp.wp_customer_sk, AVG(wr.wr_return_amt_inc_tax) AS avg_return_amt_inc_tax, SUM(wr.wr_return_quantity) AS total_return_qty FROM web_page wp JOIN web_returns wr ON wr.wr_web_page_sk = wp.wp_web_page_sk WHERE wr.wr_return_amt_inc_tax > 0 GROUP BY wp.wp_web_page_sk, wp.wp_url, wp.wp_web_page_id, wp.wp_customer_sk) SELECT pr.wp_web_page_id, pr.wp_url, c.c_customer_id, pr.avg_return_amt_inc_tax, pr.total_return_qty, CASE WHEN pr.total_return_qty > 100 THEN 'Heavy' ELSE 'Light' END AS volume_level, RANK() OVER (ORDER BY pr.avg_return_amt_inc_tax ASC) AS asc_rank, COALESCE(sr_agg.store_net_loss, 0) AS page_owner_store_net_loss FROM page_returns pr JOIN customer c ON pr.wp_customer_sk = c.c_customer_sk LEFT JOIN (SELECT sr.sr_customer_sk, SUM(sr.sr_net_loss) AS store_net_loss FROM store_returns sr WHERE sr.sr_return_quantity > 0 GROUP BY sr.sr_customer_sk) sr_agg ON sr_agg.sr_customer_sk = c.c_customer_sk WHERE pr.total_return_qty BETWEEN 10 AND 200 ORDER BY pr.total_return_qty DESC LIMIT 15
